events.onValueChange:
function(form) {
  form.get('Del_complications_in_delivery').setHidden(true);
  form.get('Del_Outcome_Delivery').setHidden(true);
  form.get('Del_Date_of_Delivery').setHidden(true);
  form.get('Del_specify_reason').setHidden(true);
  form.get('Del_Specify_complications').setHidden(true);
  form.get('Del_Newborn_Weight').setHidden(true);
  form.get('Del_Newborn_complication').setHidden(true);
  form.get('ACS_other_diagnosis').setHidden(true);


  var ht = form.get('Global_height').getValue();
  var wt = form.get('Global_weight').getValue();

  if (ht && wt) {
    form.get('BMI').setValue(((parseFloat(wt) / parseFloat(ht) / parseFloat(ht)) * 10000).toFixed(1));
  }
}

function(form) {
  var multi_select = form.get('ACS_ADULT_Diagnosis').currentRecord.value.value;
  var length = multi_select == undefined ? 0 : multi_select.length;
  var arr = []
  if (length == 0) {
    form.get("ACS_other_diagnosis").setHidden(true);
  } else {
    for (var i = 0; i < length; i++) {
      var name = multi_select[i].displayString == undefined ? multi_select[i].name : multi_select[i].displayString;
      arr.push(name);
      if (arr.includes('Other_Diagnosis'))
        form.get("ACS_other_diagnosis").setHidden(false);
      else
        form.get("ACS_other_diagnosis").setHidden(true);
    }
  }
}

function(form) {
  if (form.get('Subscription card').getValue() === 'Yes') {
    form.get('Subscription card Numbers').setHidden(false);
  } else {
    form.get('Subscription card Numbers').setHidden(true);
  }
}

